#!/usr/bin/env bash
# The wizard library below comes verbatim from the wizard skill and trips these two; the stages are clean.
# shellcheck disable=SC1087,SC2329
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Sets up one repo for the weekly dependency job (Fenro T-563): the Claude GitHub App, the
# weekly-deps environment limited to main, and its two secrets.
#
#   tools/weekly-deps/setup.sh <owner/repo>
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Environment secrets, not repo secrets: the template's set_secret writes repo-level ones.
set_env_secret() {
  local name="$1" value="$2"
  if printf '%s' "$value" | gh secret set "$name" --env "$ENVIRONMENT" --repo "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s in the %s environment\n' "$GREEN" "$RESET" "$name" "$ENVIRONMENT"
  else
    SKIPPED+=("$name: gh secret set $name --env $ENVIRONMENT --repo $REPO")
    warn "could not set $name; set it later with gh secret set $name --env $ENVIRONMENT --repo $REPO"
  fi
}

run_wizard() {

TOTAL_STAGES=5
ENVIRONMENT=weekly-deps
# Nothing here is written to disk: secrets go straight to GitHub, and pointing ENV_FILE at a path
# that never exists keeps ask_secret from offering a stored value.
ENV_FILE=/nonexistent/weekly-deps.env

REPO="${1:-}"
if [[ ! "$REPO" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]]; then
  echo "usage: $0 <owner/repo>   e.g. $0 Daniel88dev/flexi-day" >&2
  exit 2
fi

banner "Weekly dependency job: GitHub setup for $REPO"

stage "Check gh and the repository"
say "The wizard uses the GitHub CLI for the environment and its secrets."
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not signed in. Run 'gh auth login', then start the wizard again."
  exit 1
fi
if ! perm=$(gh api "repos/$REPO" --jq '.permissions.admin' 2>/dev/null); then
  warn "gh cannot see $REPO. Check the name and your access."
  exit 1
fi
if [[ "$perm" != "true" ]]; then
  warn "You need admin rights on $REPO to create environments."
  exit 1
fi
step "gh is signed in and you administer $REPO."
pause "Press Enter to continue."

stage "Claude GitHub App"
say "The job pushes and opens its PR as the Claude GitHub App, so that PR starts CI."
open_url "https://github.com/apps/claude/installations/new"
step "Pick the ${REPO%%/*} account."
step "Already installed there: GitHub shows its settings. Under 'Repository access',"
step "keep 'Only select repositories', add ${REPO#*/}, and click Save."
step "Not installed yet: choose 'Only select repositories', pick ${REPO#*/}, and click Install."
note "gh cannot read app installations, so this one is on your word."
until confirm "Does the Claude app now list ${REPO#*/} under its repositories?"; do
  say "Finish the step in the browser, then answer y."
done

stage "The $ENVIRONMENT environment"
say "Both secrets live in an environment that only the main branch may deploy from."
# On a 404 gh prints the error body to stdout, so the fallback replaces the value outright.
existing=$(gh api "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
  --jq '[.branch_policies[] | "\(.type):\(.name)"] | join(" ")' 2>/dev/null) || existing="missing"
if [[ "$existing" == "branch:main" ]]; then
  step "$ENVIRONMENT already exists and allows only main. Nothing to change."
else
  if [[ "$existing" == "missing" ]]; then
    note "No $ENVIRONMENT environment yet."
  else
    warn "$ENVIRONMENT exists with branch rules: ${existing:-none}. It will allow only main."
  fi
  if confirm "Create or update $ENVIRONMENT on $REPO with a main-only branch rule?"; then
    jq -n '{deployment_branch_policy: {protected_branches: false, custom_branch_policies: true}}' |
      gh api -X PUT "repos/$REPO/environments/$ENVIRONMENT" --input - >/dev/null
    while read -r id; do
      [[ -n "$id" ]] && gh api -X DELETE \
        "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies/$id" >/dev/null
    done < <(gh api "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
      --jq '.branch_policies[] | select(.name != "main" or .type != "branch") | .id')
    if ! gh api "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
      --jq '.branch_policies[].name' | grep -qx main; then
      gh api -X POST "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
        -f name=main -f type=branch >/dev/null
    fi
    step "$ENVIRONMENT now deploys from main only."
  else
    SKIPPED+=("the $ENVIRONMENT environment with a main-only branch rule")
    warn "Skipped. The secrets below need the environment, so they will fail without it."
  fi
fi
pause "Press Enter to continue."

stage "CLAUDE_CODE_OAUTH_TOKEN"
say "The job bills your Claude subscription through a long-lived token."
step "One token serves all five repos. If you made one for another repo, paste that."
step "Otherwise open a second terminal and run: claude setup-token"
step "Sign in when the browser asks, then copy the token it prints."
note "Save it in 1Password: it lasts a year, and the other repos need it too."
note "Input is hidden. Nothing is echoed or written to disk."
CLAUDE_CODE_OAUTH_TOKEN=""
until [[ -n "$CLAUDE_CODE_OAUTH_TOKEN" ]]; do
  ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token:"
done
set_env_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
unset CLAUDE_CODE_OAUTH_TOKEN
pause "Press Enter to continue."

stage "FENRO_TOKEN"
say "A Fenro token used only by this job, for its report notes and the tasks it files."
open_url "https://www.fenro-dashboard.com/settings"
step "Under 'Agent access', find 'Create a token'."
step "Name: weekly-deps job. Expires after: 1 year. Keep 'Can change tasks' ticked."
step "Click 'Create token' and copy the token it shows once."
step "Made one already for another repo? Paste that one instead."
note "Input is hidden. Nothing is echoed or written to disk."
FENRO_TOKEN=""
until [[ -n "$FENRO_TOKEN" ]]; do
  ask_secret FENRO_TOKEN "Paste the token:"
done
set_env_secret FENRO_TOKEN "$FENRO_TOKEN"
unset FENRO_TOKEN

say ""
say "Secrets now in $ENVIRONMENT (names only):"
gh secret list --env "$ENVIRONMENT" --repo "$REPO" 2>/dev/null | cut -f1 | sed 's/^/    /' || true
pause "Press Enter to finish."

finish
note "Next: the repo's caller workflow, then a manual run from the Actions tab."
note "Put the CLAUDE_CODE_OAUTH_TOKEN expiry on a Fenro reminder."
printf '\n'
}

run_wizard "$@"; exit
